# -*- coding: utf-8 -*-
"""Create a source-bound local review board for experimental percussion material."""
import argparse,html,json
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('root',type=Path);r=p.parse_args().root
 library=json.loads((r/'bridge-materials.json').read_text());experiment=json.loads((r/'bridge-experiments.json').read_text());rows=[]
 for s in experiment['samples']:
  plan=s['plan'];label='连续变速' if plan['rateFrom']!=plan['rateTo'] else '定速循环'
  rows.append(f'<section data-id="{s["file"]}"><h2>{html.escape(s["materialId"])} · {label}</h2><p>{plan["bpmFrom"]:.1f} → {plan["bpmTo"]:.1f} BPM，{plan["loops"]} 次循环，{plan["duration"]:.2f} 秒；鼓声音高随速率变化。</p><audio controls preload="none" src="{s["file"]}"></audio><p>接缝听感 <select><option value="">未评分</option>'+''.join(f'<option>{i}</option>' for i in range(1,6))+'</select>　重音是否清楚 <select><option value="">未判断</option><option>清楚</option><option>需要修改</option></select></p><p><label><input type="checkbox">建议进入下一轮整曲衔接试听</label></p><textarea placeholder="接缝、速度和音色的具体意见"></textarea></section>')
 content='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HarBeat 鼓桥素材审核</title><style>body{max-width:950px;margin:32px auto;padding:0 20px;background:#f6f6ef;color:#1c2c24;font:16px/1.65 system-ui}section{margin:22px 0;background:white;padding:22px;border:1px solid #d2dacd;border-radius:12px}h1{font-size:30px}h2{font-size:20px}audio,textarea{width:100%}textarea{min-height:70px}button,select{font:inherit;padding:8px}button{background:#294f37;color:white;border:0;border-radius:8px}small{color:#586a58}</style><h1>鼓桥与循环变速 · 实验试听</h1><p>先从 HIPHOP 的真实鼓分轨提取两个两小节候选。这里比较循环接缝和速度变化，暂未把鼓桥插进自动播放。每份素材保留原曲、分轨和分析指纹，人工审核仍为空。</p><p>连续变速范围为原速度的 90% → 110%，仅用鼓声实验，音高会随速度变化。整曲保调连续变速仍需后续实现和试听。半／双拍候选请在 <a href="/audition/">24 组对比试听</a> 的对应六组判断重音；BPM 比例本身不足以批准该映射。</p><button id="export">导出本轮审核记录</button><p><small>评分和备注仅保存在此浏览器。勾选建议不会自动发布素材或修改手机选曲。</small></p>'''+''.join(rows)
 data=json.dumps(dict(library=library,experiment=experiment),ensure_ascii=False).replace('<','\\u003c')
 content+='''<script>const source='''+data+''';const key='harbeat-bridge-review:'+source.experiment.samples.map(s=>s.fingerprint).join(':');let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const records={};for(const section of document.querySelectorAll('section')){const id=section.dataset.id,a=section.querySelector('audio'),selects=section.querySelectorAll('select'),box=section.querySelector('input'),notes=section.querySelector('textarea');const old=saved[id]||{};selects[0].value=old.seamScore||'';selects[1].value=old.accents||'';box.checked=old.recommend===true;notes.value=old.notes||'';const record=()=>{records[id]={seamScore:selects[0].value?Number(selects[0].value):null,accents:selects[1].value||null,recommend:box.checked,notes:notes.value,playedIntervals:[...(old.playedIntervals||[]),...Array.from({length:a.played.length},(_,i)=>[a.played.start(i),a.played.end(i)])]};localStorage.setItem(key,JSON.stringify(records))};record();section.addEventListener('change',record);notes.addEventListener('input',record);a.addEventListener('pause',record);a.addEventListener('ended',record)}document.querySelector('#export').onclick=()=>{const content={schema:'harbeat.bridge-review.v1',at:new Date().toISOString(),source,records,automaticPublish:false};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));a.href=url;a.download='harbeat-bridge-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};</script></html>'''
 (r/'bridge-review.html').write_text(content,encoding='utf-8');print(json.dumps({'materials':len(library['materials']),'samples':len(experiment['samples']),'humanApproved':0}))
if __name__=='__main__':main()
